type Region = 'Europe' | 'Africa' | 'Asia' | 'Middle East' | 'Americas' | 'Oceania';
type Status = 'draft' | 'review' | 'verified';
type Rhythm = { n: string; ts: string; u: 'q'|'e'|'s'; len: number; g: number; step: number; note: string; b: string; lines: [string,string,string][] };
type Tradition = { id: string; n: string; p: string; r: Region; la: number; lo: number; i: string[]; f: string[]; b: string; l: string; st?: Status; src: string[]; img?: string; rec?: {u:string;t:string;a:string;l:string;s:string}; h?: Rhythm };

type RecordingItem = { recording_title:string; performer?:string; recording_year?:number; archive?:string; source_url?:string|null; audio_url?:string|null; license?:string; verification_status?:string; access_model?:string; quality_notes?:string };
type RecordingTradition = { tradition_id:string; tradition_name:string; place:string; recordings:RecordingItem[]; research_status?:string };
type ImageTradition = { tradition_id:string; tradition_name:string; place:string; search_query:string };
type TraditionVideoCandidate = { url:string; page:string; title:string; creator:string; license:string; mime:string; description:string };
function ResearchVideo({query,alt}:{query:string;alt:string}) {
 const [candidate,setCandidate]=useState<TraditionVideoCandidate|null>(null);
 const [status,setStatus]=useState<'loading'|'ready'|'none'>('loading');
 const [attempt,setAttempt]=useState(0);
 useEffect(()=>{let live=true;setStatus('loading');setCandidate(null);
  const clean=(v:string)=>v.replace(/["():\\]/g,' ').replace(/\s+/g,' ').trim();
  const base=clean(query);
  const searches=[`${base} traditional music dance filetype:video`,`${base} folk dance performance filetype:video`,`${base} traditional ceremony musicians filetype:video`];
  const allowedLicense=(v:string)=>/^(CC0|CC BY(?:-SA)?(?:\s|$)|Public domain|PD|Free Art License)/i.test(v);
  const blocked=/(ai[- ]?generated|generated by ai|midjourney|stable diffusion|dall[· ]?e|synthetic|computer generated|cgi animation|animated illustration)/i;
  (async()=>{for(const term of searches){if(!live)return;try{
   const params=new URLSearchParams({action:'query',format:'json',origin:'*',generator:'search',gsrnamespace:'6',gsrsearch:term,gsrlimit:'50',prop:'imageinfo',iiprop:'url|extmetadata|mime',iiurlwidth:'640'});
   const response=await fetch(`https://commons.wikimedia.org/w/api.php?${params.toString()}`,{headers:{Accept:'application/json'}});if(!response.ok)continue;
   const data=await response.json();const pages=Object.values(data?.query?.pages||{}) as any[];
   const items=pages.map(page=>{const info=page.imageinfo?.[0],m=info?.extmetadata||{};const get=(k:string)=>String(m[k]?.value||'').replace(/<[^>]*>/g,' ').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/\s+/g,' ').trim();return {url:info?.url||'',page:info?.descriptionurl||'',title:String(page.title||''),creator:get('Artist')||get('Credit')||get('Author')||'',license:get('LicenseShortName')||get('UsageTerms')||'',mime:String(info?.mime||''),description:get('ImageDescription')}});
   const suitable=items.filter(x=>x.url&&x.page&&/^video\/(mp4|webm|ogg|quicktime|x-matroska)$/i.test(x.mime)&&x.creator&&allowedLicense(x.license)&&!blocked.test(`${x.title} ${x.description}`));
   if(suitable.length){const ranked=suitable.sort((a,b)=>{const score=(x:any)=>{const h=`${x.title} ${x.description}`.toLowerCase();const terms=base.toLowerCase().split(/\s+/).filter(w=>w.length>3);return terms.reduce((n,w)=>n+(h.includes(w)?1:0),0)};return score(b)-score(a)});if(live){setCandidate(ranked[0]);setStatus('ready')}return;}
  }catch{}}
  if(live)setStatus('none');})();
  return()=>{live=false}
 },[query,attempt]);
 const searchUrl=`https://commons.wikimedia.org/wiki/Special:MediaSearch?type=video&search=${encodeURIComponent(query+' traditional music dance performance')}`;
 return candidate?<><video className="tradition-video" controls playsInline preload="metadata" src={candidate.url} aria-label={`${alt} — documentary video`} onError={()=>{setCandidate(null);setStatus('none')}}/><a className="video-credit" href={candidate.page} target="_blank" rel="noreferrer">{candidate.title.replace(/^File:/,'')} · {candidate.creator} · {candidate.license} · video source</a></>:<div className="visual-placeholder image-placeholder"><Music2 size={23}/><span>{status==='loading'?'Searching documentary video archives…':'No matching licensed video loaded'}</span><small>WIKIMEDIA COMMONS · REAL-WORLD FOOTAGE · CC0 / CC BY / CC BY-SA / PUBLIC DOMAIN</small><div className="image-actions"><a href={searchUrl} target="_blank" rel="noreferrer">Browse video results</a><button type="button" onClick={()=>setAttempt(v=>v+1)}>Try again</button></div></div>;
}

type ArchiveAudioCandidate = { id:string; title:string; creator:string; url:string; page:string; license:string; format:string; year?:string; score:number };
function ArchiveAudioFallback({name,place}:{name:string;place:string}) {
 const [items,setItems]=useState<ArchiveAudioCandidate[]>([]);
 const [selected,setSelected]=useState('');
 const [status,setStatus]=useState<'loading'|'ready'|'none'>('loading');
 const [attempt,setAttempt]=useState(0);
 useEffect(()=>{let live=true;setItems([]);setSelected('');setStatus('loading');
  const clean=(v:string)=>v.replace(/["():\\]/g,' ').replace(/\s+/g,' ').trim();
  const nameTerm=clean(name),placeTerm=clean(place.split(',')[0]||place);
  const queries=[
   `mediatype:audio AND (title:"${nameTerm}" OR subject:"${nameTerm}" OR description:"${nameTerm}")`,
   `mediatype:audio AND (title:"${nameTerm}" OR subject:"${nameTerm}" OR creator:"${nameTerm}")`,
   `mediatype:audio AND (title:"${placeTerm}" OR subject:"${placeTerm}" OR description:"${placeTerm}")`,
   `mediatype:audio AND (title:"folk music" OR subject:"folk music") AND (title:"${placeTerm}" OR subject:"${placeTerm}" OR description:"${placeTerm}")`
  ];
  const supported=(f:any)=>{const n=String(f.name||'');const fmt=String(f.format||'').toLowerCase();return /\.(mp3|ogg|oga|wav|m4a|opus)$/i.test(n)||/(mp3|ogg vorbis|wave|wav|m4a|aac|opus)/.test(fmt)};
  const licenseLabel=(d:any)=>{const u=String(d.licenseurl||'').toLowerCase();if(u.includes('publicdomain'))return 'Public domain';if(u.includes('by-sa'))return 'CC BY-SA';if(u.includes('/licenses/by/'))return 'CC BY';if(u.includes('by-nc'))return 'CC BY-NC (noncommercial)';if(u.includes('by-nd'))return 'CC BY-ND (no derivatives)';return 'Rights not specified by archive'};
  (async()=>{const found:ArchiveAudioCandidate[]=[];const seen=new Set<string>();
   for(const q of queries){if(!live)return;try{
    const search=new URL('https://archive.org/advancedsearch.php');search.searchParams.set('q',q);for(const field of ['identifier','title','creator','licenseurl','description','subject','year'])search.searchParams.append('fl[]',field);search.searchParams.set('rows','50');search.searchParams.set('page','1');search.searchParams.set('output','json');
    const response=await fetch(search.toString());if(!response.ok)continue;const data=await response.json();const docs=data?.response?.docs||[];
    const ranked=docs.map((d:any)=>{const hay=`${d.title||''} ${d.description||''} ${(d.subject||[]).join?.(' ')||d.subject||''}`.toLowerCase();const n=name.toLowerCase(),p=placeTerm.toLowerCase();return {...d,score:(hay.includes(n)?8:0)+(hay.includes(p)?4:0)+(String(d.title||'').toLowerCase().includes(n)?5:0)+(String(d.creator||'').length?1:0)}}).sort((a:any,b:any)=>b.score-a.score);
    let inspected=0;for(const d of ranked){if(!live)return;if(!d.identifier||seen.has(d.identifier))continue;seen.add(d.identifier);if(++inspected>18)break;
     try{const mr=await fetch(`https://archive.org/metadata/${encodeURIComponent(d.identifier)}`);if(!mr.ok)continue;const meta=await mr.json();const files=(meta?.files||[]).filter(supported).filter((f:any)=>!String(f.name||'').includes('__ia_thumb')&&!String(f.name||'').includes('_thumb')&&!String(f.name||'').includes('sample'));
      files.sort((a:any,b:any)=>{const rank=(f:any)=>/\.mp3$/i.test(f.name)?0:/\.ogg$|\.oga$/i.test(f.name)?1:/\.wav$/i.test(f.name)?2:/\.m4a$/i.test(f.name)?3:4;return rank(a)-rank(b)});
      const f=files[0];if(!f)continue;const path=String(f.name).split('/').map(encodeURIComponent).join('/');const url=`https://archive.org/download/${encodeURIComponent(d.identifier)}/${path}`;
      found.push({id:String(d.identifier),title:String(d.title||name),creator:String(d.creator||'Creator not listed'),url,page:`https://archive.org/details/${encodeURIComponent(d.identifier)}`,license:licenseLabel(d),format:String(f.format||f.name.split('.').pop()||'audio'),year:String(d.year||'') ,score:d.score||0});
      if(found.length>=10)break;
     }catch{}
    }
    if(found.length>=10)break;
   }catch{}}
   if(live){found.sort((a,b)=>b.score-a.score);setItems(found);setSelected(found[0]?.id||'');setStatus(found.length?'ready':'none')}
  })();return()=>{live=false};
 },[name,place,attempt]);
 const chosen=items.find(x=>x.id===selected);
 const searchUrl=`https://archive.org/advancedsearch.php?q=${encodeURIComponent(`mediatype:audio AND (title:"${name}" OR subject:"${name}" OR description:"${place}")`)}&fl[]=identifier,title,creator&rows=50&page=1&output=json`;
 return <section className="archive-audio-picker" aria-label={`Select an audio recording for ${name}`}>
  <div className="archive-picker-heading"><div><b>Choose a recording</b><small>Searchable public audio catalogue · select a result to play it here</small></div><button type="button" onClick={()=>setAttempt(v=>v+1)}>Refresh results</button></div>
  {status==='loading'&&<div className="empty-recording"><AudioLines size={30}/><span><b>Finding playable recordings…</b><small>Searching Internet Archive for {name} and {place}</small></span></div>}
  {status==='none'&&<div className="empty-recording"><AudioLines size={30}/><span><b>No direct audio file found automatically</b><small>Try the broader archive search for this tradition.</small><a href={searchUrl} target="_blank" rel="noreferrer">Open all archive search results</a></span></div>}
  {items.length>0&&<><label className="archive-audio-label" htmlFor={`archive-audio-${name.replace(/[^a-z0-9]/gi,'-')}`}>Available recordings ({items.length})</label><select id={`archive-audio-${name.replace(/[^a-z0-9]/gi,'-')}`} className="archive-audio-select" value={selected} onChange={e=>setSelected(e.target.value)}>{items.map((item,i)=><option key={item.id} value={item.id}>{i+1}. {item.title} — {item.creator}</option>)}</select>
   {chosen&&<div className="recording-track archive-audio-candidate"><div className="empty-recording"><AudioLines className="recording-wave" size={30}/><span><b>{chosen.title}</b><small>{chosen.creator}{chosen.year?` · ${chosen.year}`:''} · Internet Archive · {chosen.license}</small></span></div><audio controls preload="none" src={chosen.url} aria-label={`Play ${chosen.title} for ${name}`} onError={()=>setItems(prev=>prev.filter(x=>x.id!==chosen.id))}/><p className="credit-line"><a href={chosen.page} target="_blank" rel="noreferrer">Original archive item and attribution</a> · {chosen.format}. {chosen.license==='Rights not specified by archive'?'Playback link only; reuse rights require separate review.':'Check item terms before downloading or redistribution.'}</p></div>}
   <a className="archive-more-results" href={searchUrl} target="_blank" rel="noreferrer">See more archive results</a></>}
 </section>;
}

type MediaItem={kind:'audio'|'video'|'archive'|'youtube';url?:string;id?:string;title:string;credit?:string;license?:string;page?:string;note?:string};
let mediaCache:Promise<Record<string,MediaItem[]>>|null=null;
const loadMedia=()=>mediaCache??(mediaCache=fetch(`${import.meta.env.BASE_URL}media.json`).then(r=>r.ok?r.json():{}).then((j:any)=>j?.traditions||{}).catch(()=>({})));
const https=(u:string)=>u.replace(/^http:\/\//i,'https://');
function SafeAudio({src,label,testId}:{src:string;label:string;testId?:string}){const [bad,setBad]=useState(false);
 return bad?<p className="player-note">This recording couldn’t load here — its host may block playback from other sites.</p>:<audio controls preload="none" src={https(src)} aria-label={label} data-testid={testId} onError={()=>setBad(true)}/>}
function SafeVideo({src,label}:{src:string;label:string}){const [bad,setBad]=useState(false);
 return bad?<p className="player-note">This video couldn’t load here — its host may block playback from other sites.</p>:<video className="embed-video" controls playsInline preload="metadata" src={https(src)} aria-label={label} onError={()=>setBad(true)}/>}
function CuratedMedia({id,name}:{id:string;name:string}){const [items,setItems]=useState<MediaItem[]>([]);
 useEffect(()=>{let live=true;loadMedia().then(m=>{if(live)setItems(m[id]||[])});return()=>{live=false}},[id]);
 return <>{items.map((m,i)=><div className="recording-track" key={`m-${id}-${i}`}>
  {m.kind==='audio'&&m.url&&<SafeAudio src={m.url} label={`Play ${m.title}`}/>}
  {m.kind==='video'&&m.url&&<SafeVideo src={m.url} label={`${name} — ${m.title}`}/>}
  {m.kind==='archive'&&m.id&&<iframe className="embed-video" src={`https://archive.org/embed/${encodeURIComponent(m.id)}`} title={m.title} loading="lazy" allowFullScreen/>}
  {m.kind==='youtube'&&m.id&&<iframe className="embed-video" src={`https://www.youtube-nocookie.com/embed/${encodeURIComponent(m.id)}`} title={m.title} loading="lazy" allow="encrypted-media; picture-in-picture" allowFullScreen/>}
  <p className="credit-line">{m.title}{m.credit?` · ${m.credit}`:''}{m.license?` · ${m.license}`:''}{m.page&&<> · <a href={m.page} target="_blank" rel="noreferrer">source</a></>}</p></div>)}</>}
function useCurated(id:string){const [items,setItems]=useState<MediaItem[]|null>(null);
 useEffect(()=>{let live=true;setItems(null);loadMedia().then(m=>{if(live)setItems(m[id]||[])});return()=>{live=false}},[id]);return items}
const ytSrc=(id:string)=>`https://www.youtube-nocookie.com/embed/${encodeURIComponent(id)}?rel=0&modestbranding=1&playsinline=1`;
const EMBED_PLAYERS=(import.meta as any).env?.VITE_EMBED_PLAYERS!=='false';
function YouTubePlayer({id,title,className}:{id:string;title:string;className?:string}){
 if(!EMBED_PLAYERS)return <a className={`${className||'embed-video'} yt-card`} href={`https://www.youtube.com/watch?v=${id}`} target="_blank" rel="noreferrer" aria-label={`Watch on YouTube: ${title}`}><span className="yt-play" aria-hidden="true">▶</span><span>Watch on YouTube</span></a>;
 return <iframe className={className||'embed-video'} src={ytSrc(id)} title={title} loading="lazy" allow="accelerometer; encrypted-media; picture-in-picture; fullscreen" allowFullScreen referrerPolicy="strict-origin-when-cross-origin" data-testid={`player-${id}`}/>}
function VideoSlot({id,name,query,alt}:{id:string;name:string;query:string;alt:string}){
 const items=useCurated(id);const [sel,setSel]=useState(0);
 if(items===null)return <div className="slot-loading">Loading video…</div>;
 const yt=items.filter(x=>x.kind==='youtube'&&x.id);
 if(!yt.length)return <ResearchVideo query={query} alt={alt}/>;
 const cur=yt[Math.min(sel,yt.length-1)];
 return <div className="video-slot" data-testid="video-slot">
  <YouTubePlayer id={cur.id!} title={`${name} — ${cur.title}`} className="embed-video slot-player"/>
  {yt.length>1&&<div className="player-tabs" role="tablist" aria-label={`${name} videos`}>{yt.map((v,i)=><button key={v.id} type="button" role="tab" aria-selected={i===sel} className={i===sel?'on':''} onClick={()=>setSel(i)} data-testid={`video-tab-${i+1}`}>Video {i+1}</button>)}</div>}
  <p className="credit-line"><b>{cur.title}</b> · <a href={`https://www.youtube.com/watch?v=${cur.id}`} target="_blank" rel="noreferrer">Open on YouTube</a>{cur.note&&<><br/><i>{cur.note}</i></>}</p></div>}
function TraditionAudio({tradition,research}:{tradition:Tradition;research?:RecordingTradition}) {
 const curated=useCurated(tradition.id);const hasCurated=!!curated&&curated.some(x=>x.kind==='youtube');
 const direct=[...(tradition.rec?[{title:tradition.rec.t,performer:tradition.rec.a,license:tradition.rec.l,source_url:tradition.rec.s,audio_url:tradition.rec.u}]:[]),...(research?.recordings||[]).filter(x=>x.audio_url)];
 const sourceOnly=(research?.recordings||[]).filter(x=>!x.audio_url&&x.source_url);
 return <div className="recording-tracks">
  {direct.map((r:any,i)=><div className="recording-track" key={`${r.title||r.recording_title}-${i}`}><div className="empty-recording"><AudioLines className="recording-wave" size={34}/><span><b>{r.title||r.recording_title}</b><small>{r.performer||r.performer_name||'Performer not listed'} · {r.license||'Rights information not supplied'}</small></span></div><SafeAudio src={r.audio_url||r.u} label={`Play recording for ${tradition.n}`} testId={`audio-recording-${tradition.id}-${i}`}/>{(r.source_url||r.s)&&<p className="credit-line"><a href={r.source_url||r.s} target="_blank" rel="noreferrer">Open original recording source</a></p>}</div>)}
  {sourceOnly.map((r,i)=>{const u=r.source_url!;let yt='';try{const x=new URL(u);if(/(^|\.)youtube\.com$/.test(x.hostname))yt=x.searchParams.get('v')||'';else if(x.hostname==='youtu.be')yt=x.pathname.slice(1)}catch{}
   const sc=/^https:\/\/soundcloud\.com\//.test(u);
   return <div className="recording-track" key={`source-${i}`}>
    {yt&&!hasCurated&&/^[\w-]{6,20}$/.test(yt)&&<iframe className="embed-video" src={`https://www.youtube-nocookie.com/embed/${yt}`} title={`${r.recording_title} — video player`} loading="lazy" allow="encrypted-media; picture-in-picture" allowFullScreen referrerPolicy="strict-origin-when-cross-origin"/>}
    {sc&&<iframe className="embed-audio" src={`https://w.soundcloud.com/player/?url=${encodeURIComponent(u)}&visual=false&show_comments=false`} title={`${r.recording_title} — audio player`} loading="lazy" allow="autoplay"/>}
    <p className="credit-line">{yt||sc?'Playing in app · ':'Listen to a real archival recording: '}<a href={u} target="_blank" rel="noreferrer">{r.recording_title} — {r.archive||'Original archive'}</a> · {r.license||'Rights not specified'}</p></div>})}
  {!hasCurated&&<ArchiveAudioFallback name={tradition.n} place={research?.place||tradition.p}/>}
 </div>;
}

